import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import * as simpleIcons from 'simple-icons';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const icons = Object.values(simpleIcons).map((icon) => ({
  slug: icon.slug,
  title: icon.title,
  hex: icon.hex,
}));

const out = `// Auto-generated by scripts/generate-simple-icons-manifest.mjs
// Do not edit manually. Re-run \`pnpm icons:generate\` after upgrading simple-icons.

export interface SimpleIconEntry {
  slug: string;
  title: string;
  hex: string;
}

export const simpleIconManifest: readonly SimpleIconEntry[] = ${JSON.stringify(icons, null, 2)};
`;

const target = path.join(__dirname, '..', 'src', 'shared', 'logo', 'simpleIconManifest.ts');
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(target, out);
console.log(`Wrote ${icons.length} icons to ${target}`);
